// Разовая пометка каталога тегом needs:data.
// Пусто хоть одно из artmellio.style/material/room/palette -> тег есть.
// Всё заполнено -> тега нет. Другие теги не трогаем: tagsAdd/tagsRemove
// работают только с указанным тегом.
const TAG = 'needs:data';
const token = $input.first().json.access_token;
const url = 'https://kmfmxn-r4.myshopify.com/admin/api/2026-07/graphql.json';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Долгий прогон: Shopify иногда рвёт соединение (ECONNRESET) или просит
// подождать (429). Повторяем до 4 раз с растущей паузой.
const call = async (query, variables) => {
  let last;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      return await this.helpers.httpRequest({
        method: 'POST', url,
        headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
        body: { query, variables }, json: true,
      });
    } catch (e) {
      last = e;
      await sleep(1000 * (attempt + 1));
    }
  }
  throw last;
};

const listQ = `query($cursor: String) {
  products(first: 100, after: $cursor, query: "status:active OR status:draft") {
    pageInfo { hasNextPage endCursor }
    nodes {
      id title tags
      style: metafield(namespace: "artmellio", key: "style") { value }
      material: metafield(namespace: "artmellio", key: "material") { value }
      room: metafield(namespace: "artmellio", key: "room") { value }
      palette: metafield(namespace: "artmellio", key: "palette") { value }
    }
  }
}`;
const addM = `mutation($id: ID!, $tags: [String!]!) { tagsAdd(id: $id, tags: $tags) { userErrors { message } } }`;
const removeM = `mutation($id: ID!, $tags: [String!]!) { tagsRemove(id: $id, tags: $tags) { userErrors { message } } }`;
const empty = (v) => !v || !v.value || String(v.value).trim() === '' || String(v.value).trim() === '[]';

const all = [];
let cursor = null;
let pages = 0;
do {
  const r = await call(listQ, { cursor });
  if (r.errors) throw new Error('Shopify: ' + JSON.stringify(r.errors));
  const page = r.data.products;
  all.push(...page.nodes);
  cursor = page.pageInfo.hasNextPage ? page.pageInfo.endCursor : null;
  pages += 1;
} while (cursor && pages < 100);

let added = 0, removed = 0, untouched = 0;
const errors = [];
let n = 0;
for (const p of all) {
  const missing = ['style', 'material', 'room', 'palette'].some((k) => empty(p[k]));
  const has = (p.tags || []).includes(TAG);
  let m = null;
  if (missing && !has) m = addM;
  if (!missing && has) m = removeM;
  if (!m) { untouched += 1; continue; }
  const r = await call(m, { id: p.id, tags: [TAG] });
  const errs = (r.errors && r.errors.map((e) => e.message)) ||
    (r.data && (r.data.tagsAdd || r.data.tagsRemove).userErrors.map((e) => e.message)) || [];
  if (errs.length) errors.push(p.title + ': ' + errs.join('; '));
  else if (m === addM) added += 1; else removed += 1;
  n += 1;
  if (n % 20 === 0) await sleep(1500); // не упираться в лимит запросов Shopify
}

return [{ json: {
  проверено: all.length,
  тег_поставлен: added,
  тег_снят: removed,
  без_изменений: untouched,
  ошибки: errors.length ? errors.slice(0, 20) : 'нет',
} }];
